sql:
SELECT l.ordered_on AS day, 'total' AS series, SUM(l.sales_dollars) AS value
FROM sales.invoice_line l
WHERE l.item_no IN (
  SELECT item_no FROM sales.item WHERE category_current IN (
    SELECT category_code FROM sales.category WHERE category_name ILIKE '%VODKA%'
  )
)
AND l.ordered_on >= '2016-01-01'
GROUP BY day
ORDER BY day;
